import React, { useEffect, useState } from "react";
import UsageBarChart from "./components/UsageBarChart";
import UsagePieChart from "./components/UsagePieChart";
import ActivityList from "./components/ActivityList";
import KpiCards from "./components/KpiCards";


export default function App() {
  const [summary, setSummary] = useState([]);
  const [sessions, setSessions] = useState([]);

  useEffect(() => {
    fetch("http://localhost:5000/api/analytics/summary")
      .then(res => res.json())
      .then(setSummary);

    fetch("http://localhost:5000/api/analytics")
      .then(res => res.json())
      .then(setSessions);
  }, []);

  const totalTime = sessions.reduce((sum, s) => sum + s.duration, 0);

const uniqueSites = new Set(
  sessions.map(s => new URL(s.domain).hostname)
).size;

// Simple productivity rule (example)
const productiveSites = ["chatgpt.com", "github.com", "leetcode.com"];
const productiveTime = sessions
  .filter(s => productiveSites.some(p => s.domain.includes(p)))
  .reduce((sum, s) => sum + s.duration, 0);

const productivityScore = totalTime
  ? Math.round((productiveTime / totalTime) * 100)
  : 0;


  return (
    <div className="container">
      <h1>📊 Website Activity Dashboard</h1>

      <div className="card">
        <h2>Daily Usage (Bar)</h2>
        <UsageBarChart data={summary} />
      </div>

      <div className="card">
        <h2>Usage Share (Pie)</h2>
        <UsagePieChart data={summary} />
      </div>

      <div className="card">
        <h2>📱 App Activity</h2>
        <ActivityList sessions={sessions} />
      </div>
    </div>
  );
}
